CREATE TABLE systypes (typeid smallint PRIMARY KEY, typename varchar(50), typeno int)
CREATE TABLE periods (periodno smallint PRIMARY KEY, lastdate_in_period date)
CREATE TABLE gltrans (counterindex int AUTO_INCREMENT PRIMARY KEY, type smallint, typeno bigint, chequeno int, trandate date, periodno smallint, account varchar(20), narrative varchar(200), amount double, posted tinyint DEFAULT 0, jobref varchar(20), tag tinyint, location varchar(5), userid varchar(20), debtorno varchar(10), branchcode varchar(10), stockid varchar(20), orderno int, lineno int)
CREATE TABLE paymentterms (termsindicator char(4) PRIMARY KEY, terms varchar(40), daysbeforedue smallint, dayinfollowingmonth smallint, statementperiods int, agefrom int, ageto int)
CREATE TABLE binmoves (binmoveno int AUTO_INCREMENT PRIMARY KEY, stkmoveno int, stockid varchar(20), loccode varchar(5), binid varchar(10), bin varchar(10), qty double, newqoh double, userid varchar(20), trandate datetime, cost double, transno int, type int, receivedate datetime)
CREATE TABLE debtortranstaxes (debtortransid int, taxauthid int, taxamount double, PRIMARY KEY (debtortransid, taxauthid))
CREATE TABLE stockmovestaxes (stkmoveno int, taxauthid int, taxrate double, taxontax tinyint, taxcalculationorder tinyint, PRIMARY KEY (stkmoveno, taxauthid))
CREATE TABLE stockspecials (stockid varchar(20), loccode varchar(5), qtysold double, qtymax double, price double, startdate date, enddate date, PRIMARY KEY (stockid, loccode))
CREATE TABLE earned_commission (id int AUTO_INCREMENT PRIMARY KEY, stkmoveno int, salesperson varchar(4), amount double, rate double, transno int, type int, trandate date, debtorno varchar(10), stockid varchar(20))
CREATE TABLE oms (orderno int PRIMARY KEY, status int, status_id int, invoiced tinyint, transno int)
CREATE TABLE companies (coycode int PRIMARY KEY, coyname varchar(50), debtorsact varchar(20), freightact varchar(20), gllink_debtors tinyint, gllink_stock tinyint, pytdiscountact varchar(20), exchangediffact varchar(20), purchasesexchangediffact varchar(20), retainedearnings varchar(20), creditorsact varchar(20), payrollact varchar(20), grnact varchar(20), currencydefault char(3))
CREATE TABLE cogsglpostings (id int AUTO_INCREMENT PRIMARY KEY, area char(3), stkcat varchar(6), glcode varchar(20), salestype char(2))
CREATE TABLE salesglpostings (id int AUTO_INCREMENT PRIMARY KEY, area char(3), stkcat varchar(6), discountglcode varchar(20), salesglcode varchar(20), salestype char(2))
CREATE TABLE invglpostings (id int AUTO_INCREMENT PRIMARY KEY, area char(3), stkcat varchar(6), glcode varchar(20), salestype char(2))
CREATE TABLE chartmaster (accountcode varchar(20) PRIMARY KEY, accountname varchar(50), group_ varchar(30))
CREATE TABLE accountgroups (groupname varchar(30) PRIMARY KEY, sectioninaccounts int, pandl tinyint, sequenceintb int, parentgroupname varchar(30))
CREATE TABLE stockcategory (categoryid varchar(6) PRIMARY KEY, categorydescription varchar(20), stocktype char(1), stockact varchar(20), adjglact varchar(20), purchpricevaract varchar(20), materialuseagevarac varchar(20), wipact varchar(20))
CREATE TABLE salesman (salesmancode varchar(4) PRIMARY KEY, salesmanname varchar(30), commissionrate1 double, commlock tinyint)
CREATE TABLE commissionoverride (stockid varchar(20), salesmancode varchar(4), commpct double)
CREATE TABLE loyaltytrans (id int AUTO_INCREMENT PRIMARY KEY, transid int, debtorno varchar(10), branchcode varchar(10), amount double, spentpoints double, postdate date, comments text)
CREATE TABLE orderdeliverydifferenceslog (orderno int, orderlineno int, stockid varchar(20), quantitydiff double, debtorno varchar(10), branch varchar(10), can_or_bo char(3))
CREATE TABLE product_types (label varchar(5) PRIMARY KEY, reducesstock tinyint)
